import { handle, ok } from "@/lib/http";
import { listInterviews, requireProfile } from "@/lib/repo";
import { CreateInterviewBody } from "@/lib/interview/schemas";
import { startInterview } from "@/lib/interview/service";

export const dynamic = "force-dynamic";

export const GET = handle(async () => {
  const profile = requireProfile();
  return ok({ interviews: listInterviews(profile.id) });
});

/** Create an interview. The opening question is generated by POST /api/interviews/[id]/reply with an empty answer. */
export const POST = handle(async (req: Request) => {
  const profile = requireProfile();
  const body = CreateInterviewBody.parse(await req.json());
  return ok({ interview: startInterview(profile, body) }, { status: 201 });
});
